  `grade` varchar(20) GENERATED ALWAYS AS (case when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 80 then '1-Highest' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 75 then '2-Higher' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 70 then '3-High' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 65 then '4-High Average' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 60 then '5-Average' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 55 then '6-Low Average' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 50 then '7-Low' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 40 then '8-Lower' else '9-Lowest' end) STORED,
  `remarks` varchar(100) GENERATED ALWAYS AS (case when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 80 then 'Highest' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 75 then 'Higher' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 70 then 'High' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 65 then 'High Average' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 60 then 'Average' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 55 then 'Low Average' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 50 then 'Low' when round(coalesce(`class_score`,0) / 60 * 50,0) + round(coalesce(`exam_score`,0) / 100 * 50,0) >= 40 then 'Lower' else 'Lowest' end) STORED
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

